function defaultRange(days=state.days){const dates=[...new Set(data.salesDaily.map(x=>x.date))].sort(),endDate=dates.at(-1);if(!endDate)return {start:today()+'T00:00',end:tomorrow()+'T00:00'};const end=new Date(endDate+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);const start=new Date(end);start.setUTCDate(start.getUTCDate()-days);return {start:start.toISOString().slice(0,10)+'T00:00',end:end.toISOString().slice(0,10)+'T00:00'};}
