function countDate(stock){if(!stock?.countedAt&&!stock?.date&&!stock?.countDate)return 'Sem contagem registrada';const value=stock.countedAt||stock.date||stock.countDate;const time=stock.precision||stock.countedAtPrecision;const hasTime=String(value).includes('T')&&time!=='date'&&time!=='day';const formatted=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/New_York',day:'2-digit',month:'2-digit',year:'numeric',...(hasTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(value.includes('T')?value:value+'T12:00:00-04:00'));const moment={before:'antes da abertura',before_opening:'antes da abertura',during:'durante o expediente',after:'após o fechamento',after_closing:'após o fechamento','Antes da abertura':'antes da abertura','Durante a operação':'durante a operação','Após o fechamento':'após o fechamento'}[stock.moment];return `${formatted}${moment?' · '+moment:''}`;}
function countQuantity(stock){const qty=stock.qty??stock.knownSubtotal;return qty==null?'Sem contagem':`${preciseNumber(qty)} ${e(stock.uom||'')}`;}
