async function openWorkspace(route=state.route){
 bootError=null;loadingScreen();
 try{await refreshData();if(loginRoutes.includes(route))route='overview';goto(route);}
 catch(error){if(error.status===401||error.status===403){session=null;render();}else{bootError=error.name==='TimeoutError'?'A consulta demorou mais que o esperado. Seu login continua ativo.':error.message;loadingScreen();}}
}
