  try{if(local.recipePhotos[id]?.storage==='s3')await saveCloudPhoto('recipes',id,null);await saveLocal(next);local=next;section.outerHTML=recipePhotoView(recipeCurrent(id));icons();toast('Foto removida do cadastro.');}
