function editRecipe(id){
  const r=recipeCurrent(id);if(!r?.componentsLoaded)return;
  recipeEditor={id,components:structuredClone(r.components),dirty:false,pickerOpen:false,query:'',kind:'all'};
  openModal('Editar ingredientes',`<div class="eyebrow">${e(r.name)} · versão ${r.version}</div><div class="recipe-edit-summary"><span>Rendimento preservado <strong>${recipeYield(r)}</strong></span><span class="validation-tag">${icon('hard-drive')}Edição local</span></div><form id="recipe-edit-form"><div class="section-title">Composição da receita <span id="recipe-edit-count" class="pill-count"></span></div><div id="recipe-edit-rows"></div><div class="recipe-add-bar">${btn('Adicionar item','recipe-picker','plus')}</div><section id="recipe-picker" class="recipe-picker hidden"><div class="section-title">Encontrar no catálogo ${btn('Fechar busca','recipe-picker-close','x','ghost sm')}</div><div class="input-wrap">${icon('search')}<input id="recipe-item-search" data-input="recipe-item-search" placeholder="Busque por nome, internal name ou SKU" aria-label="Buscar ingrediente no catálogo"></div><div id="recipe-picker-results"></div></section><p class="error-text" id="recipe-error" role="alert" tabindex="-1"></p></form><div class="recipe-local-note">${icon('info')}As alterações ficam salvas neste navegador. Conversões e rendimento continuam iguais aos do cadastro. Ao trocar a unidade, confira a quantidade digitada.</div>`,`${btn('Cancelar','recipe-cancel')}${btn('Salvar alterações','save-recipe','check','primary')}`,{drawer:true,className:'recipe-drawer recipe-edit-drawer',kind:'recipe-edit'});
  renderRecipeEditor();
}
function componentUnits(c){
  const item=ingredientItems().find(x=>x.id===c.itemId);
  const units=[...(item?.units||[])];
  if(!units.some(u=>u.itemUnitId===c.itemUnitId))units.unshift({itemUnitId:c.itemUnitId,id:c.uomId,name:c.uom,legacy:true});
  return units;
}
function renderRecipeEditor(){
  const rows=recipeEditor.components;
  $('#recipe-edit-count').textContent=`${rows.length} ${rows.length===1?'item':'itens'}`;
  $('#recipe-edit-rows').innerHTML=rows.length?rows.map((c,i)=>`<section class="recipe-edit-row" data-component-row="${e(c.id)}"><div class="recipe-edit-item"><span class="recipe-item-icon">${icon(c.kind==='packaging'?'package':c.subRecipeId?'cooking-pot':'wheat')}</span><div><strong>${e(recipeIngredientName(c))}</strong><small>${e(c.sku||'Sem SKU')}${componentContext(c)?` · ${e(componentContext(c))}`:''}</small></div><button class="icon-btn recipe-remove" type="button" data-action="recipe-remove" data-index="${i}" aria-label="Remover ${e(recipeIngredientName(c))}">${icon('trash-2')}</button></div><div class="recipe-edit-controls"><div class="field"><label for="recipe-qty-${i}">Quantidade</label><input id="recipe-qty-${i}" type="number" step="any" min="0" required value="${e(c.quantity)}" data-recipe-index="${i}" data-recipe-field="quantity" aria-label="Quantidade de ${e(recipeIngredientName(c))}"></div><div class="field"><label for="recipe-unit-${i}">Unidade</label><select id="recipe-unit-${i}" data-recipe-index="${i}" data-recipe-field="unit" aria-label="Unidade de ${e(recipeIngredientName(c))}">${componentUnits(c).map(u=>`<option value="${e(u.itemUnitId)}" ${u.itemUnitId===c.itemUnitId?'selected':''}>${e(u.name)}${u.legacy?' (cadastro original)':''}</option>`).join('')}</select></div><div class="field"><label for="recipe-kind-${i}">Tipo</label><select id="recipe-kind-${i}" data-recipe-index="${i}" data-recipe-field="kind" aria-label="Tipo de ${e(recipeIngredientName(c))}"><option value="ingredient" ${c.kind==='ingredient'?'selected':''}>Ingrediente</option><option value="packaging" ${c.kind==='packaging'?'selected':''}>Embalagem</option></select></div></div>${c.notes?`<details class="component-observation"><summary>Observações</summary><p class="component-note">${e(c.notes)}</p></details>`:''}</section>`).join(''):`<div class="recipe-empty">${icon('list-plus')}<h3>A receita está sem itens</h3><p>Adicione um ingrediente ou salve a composição vazia, se esse for o cadastro desejado.</p></div>`;
  icons();
}
function recipePicker(){recipeEditor.pickerOpen=true;$('#recipe-picker').classList.remove('hidden');renderRecipePicker();$('#recipe-item-search').focus();}
function renderRecipePicker(){
  const recipe=recipeBase(recipeEditor.id),q=norm(recipeEditor.query);
  const candidates=ingredientItems().filter(x=>x.active&&x.units?.length&&x.id!==recipe.outputItemId&&norm([x.name,x.internalName,x.sku].join(' ')).includes(q));
  $('#recipe-picker-results').innerHTML=candidates.length?`<p class="recipe-result-count">${candidates.length} itens encontrados${candidates.length>8?' · refine a busca para ver outros':''}</p>${candidates.slice(0,8).map(x=>`<button type="button" class="recipe-pick-item" data-action="recipe-add" data-id="${x.id}"><span class="recipe-item-icon">${icon(x.type==='prepared'?'cooking-pot':'package')}</span><span><strong>${e(x.type==='prepared'?(x.internalName||x.name):x.name)}</strong><small>${e(x.sku||'Sem SKU')} · ${x.units.length} ${x.units.length===1?'unidade cadastrada':'unidades cadastradas'}</small></span>${icon('plus')}</button>`).join('')}`:`<div class="recipe-empty"><p>Nenhum item ativo com unidade cadastrada encontrado.</p></div>`;
  icons();
}
function recipeAdd(id){
  const item=ingredientItems().find(x=>x.id===id);if(!item?.active||!item.units?.length)return;
  const unit=item.units.find(u=>u.base)||item.units.find(u=>u.stocktake)||item.units[0];
  const c=componentFromItem(item,unit,{id:`local-${crypto.randomUUID()}`,locationId:recipeBase(recipeEditor.id).locationId||null});
  recipeEditor.components.push(c);recipeEditor.dirty=true;
  renderRecipeEditor();recipeEditor.pickerOpen=false;$('#recipe-picker').classList.add('hidden');
  $('#recipe-error').textContent='';$(`#recipe-qty-${recipeEditor.components.length-1}`)?.focus();
}
function recipeRemove(index){recipeEditor.components.splice(index,1);recipeEditor.dirty=true;renderRecipeEditor();}
function updateRecipeField(el){
  const c=recipeEditor?.components[Number(el.dataset.recipeIndex)];if(!c)return;
  if(el.dataset.recipeField==='quantity')c.quantity=el.value;
  else if(el.dataset.recipeField==='unit'){
    const unit=componentUnits(c).find(x=>x.itemUnitId===el.value);if(!unit)return;
    c.itemUnitId=unit.itemUnitId;c.uomId=unit.id;c.uom=unit.abbreviation||unit.name;c.uomName=unit.name;c.unitFactor=unit.factor;
  }else if(el.dataset.recipeField==='kind')c.kind=el.value;
  recipeEditor.dirty=true;$('#recipe-error').textContent='';
}
async function saveRecipe(){
  if(!$('#recipe-edit-form').reportValidity())return;
  const id=recipeEditor.id,recipe=recipeBase(id);
  try{const next=saveRecipeDraft(local,recipe,recipeEditor.components,ingredientItems(),data.recipes,()=>{});await saveLocal(next);local=next;}
  catch(error){$('#recipe-error').textContent=error.name==='QuotaExceededError'?'Não foi possível salvar: o armazenamento do navegador está cheio. Exporte um backup e tente novamente.':error.message;$('#recipe-error').focus();return;}
  recipeEditor.dirty=false;closeModal(true);render();showRecipe(id);toast('Nova versão da receita salva no banco.');
}
async function restoreRecipe(id){
  const next={...local,recipeEdits:{...local.recipeEdits}};
  delete next.recipeEdits[id];
  try{await saveLocal(next);}catch{toast('Não foi possível restaurar a composição. Tente novamente.','circle-alert');return;}
  local=next;showRecipe(id);render();toast('Composição original restaurada nesta prévia.');
}
function requestRecipeDiscard(){
  if(!$('#recipe-discard-guard')){
    const footer=$('#overlay-root .modal-foot');footer.insertAdjacentHTML('afterbegin',`<div id="recipe-discard-guard" class="recipe-discard-guard" role="alert"><span>Há alterações não salvas.</span>${btn('Continuar editando','recipe-keep','', 'sm')}${btn('Descartar alterações','recipe-discard','', 'sm')}</div>`);icons();
  }
  $('#recipe-discard-guard button')?.focus();return false;
}
function cancelRecipe(){if(recipeEditor?.dirty)return requestRecipeDiscard();const id=recipeEditor.id;closeModal(true);showRecipe(id);}
function discardRecipe(){const id=recipeEditor.id;recipeEditor.dirty=false;closeModal(true);showRecipe(id);}
function showOrder(id){const x=records('orders').find(x=>x.id===id);if(!x)return;if(!x.local&&data.operationMeta){operationUI.showOrder(x);if(x.status==='draft')$('#overlay-root .modal-foot').insertAdjacentHTML('afterbegin',btn('Marcar como pedido','cloud-order-advance','check','primary',`data-id="${x.id}"`));if(['ordered','partially_received'].includes(x.status))$('#overlay-root .modal-foot').insertAdjacentHTML('afterbegin',btn('Registrar recebimento','cloud-receipt','','primary',`data-id="${x.id}"`));return;}openModal(`Ordem ${e(shortId(x))}`,`<div class="eyebrow">${e(x.supplierName)}${localMark(x)}</div><h3 class="item-detail-title">${e(x.locationName)}</h3><div class="detail-grid">${pair('Status',status(x.status))}${pair('Entrega prevista',date(x.expectedAt))}${pair('Itens',x.lineCount||x.lines?.length||0)}${pair('Total',money(x.total))}</div>${linesTable(x.lines)}${x.notes?`<div class="section-title">Observações</div><p class="item-detail-desc">${e(x.notes)}</p>`:''}<div style="margin-top:20px">${notice(x.local?'Esta ordem é uma simulação local. Avançar o status não envia o pedido ao fornecedor nem movimenta estoque.':'Ordem consultada no banco. As linhas detalhadas não estão neste extrato; o registro permanece somente para consulta.',true)}</div>${historyView(x)}`,x.local&&x.status==='draft'?localFoot('order-advance','Marcar como pedido').replace('data-action="order-advance"',`data-action="order-advance" data-id="${x.id}"`):x.local&&x.status==='ordered'?localFoot('order-advance','Simular recebimento').replace('data-action="order-advance"',`data-action="order-advance" data-id="${x.id}"`):btn('Fechar','close'),{drawer:true});}
function linesTable(lines){return lines?.length?`<div class="section-title">Itens da operação</div><div class="table-wrap"><table><thead><tr><th>ITEM</th><th>QTY.</th><th>UOM</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${e(l.name)}</td><td>${preciseNumber(l.qty)}</td><td>${e(l.uom)}</td></tr>`).join('')}</tbody></table></div>`:'';}
function historyView(x){return x.history?.length?`<div class="section-title">Histórico local</div><div class="timeline">${x.history.map(h=>`<div class="timeline-item"><strong>${e(h.text)}</strong><span>${date(h.at)} · Validação local</span></div>`).join('')}</div>`:'';}
function showTransfer(id){const x=records('transfers').find(x=>x.id===id);if(!x)return;if(!x.local&&data.operationMeta){operationUI.showTransfer(x);const step=x.status==='submitted'?'approve':['approved','in_progress'].includes(x.status)?'dispatch':null;const footer=$('#overlay-root .modal-foot');if(step)footer.insertAdjacentHTML('afterbegin',btn(step==='approve'?'Aprovar quantidades':'Registrar expedição','cloud-transfer-step','','primary',`data-id="${x.id}" data-step="${step}"`));if(x.status==='in_progress')for(const shipment of x.dispatches||[])if(shipment.lines.some(l=>l.quantity>l.receivedQuantity))footer.insertAdjacentHTML('afterbegin',btn('Receber despacho '+shipment.id.slice(0,6),'cloud-transfer-step','','',`data-id="${x.id}" data-step="receive" data-shipment="${shipment.id}"`));return;}const action=({draft:'Aprovar transferência',approved:'Registrar expedição',dispatched:'Confirmar recebimento'})[x.status];openModal('Transferência interna',`<div class="eyebrow">${e(shortId(x))}${localMark(x)}</div><h3 class="item-detail-title">${e(x.fromLocationName)} ${icon('arrow-right')} ${e(x.toLocationName)}</h3><div class="detail-grid">${pair(x.kind==='internal_request'?'Status da solicitação':'Status',status(x.status))}${pair('Data necessária',date(x.date))}</div>${linesTable(x.lines)}${x.notes?`<div class="section-title">Observações</div><p>${e(x.notes)}</p>`:''}<div style="margin-top:20px">${notice(x.local?'O fluxo pode ser validado até o recebimento. Todas as etapas ficam locais, sem baixa ou entrada de estoque.':'Solicitação interna concluída no banco. O extrato não certifica as quantidades expedidas ou recebidas e não contém movimentações de transferência.',true)}</div>${historyView(x)}`,btn('Imprimir','transfer-print','printer','',`data-id="${e(x.id)}"`)+(x.local&&action?localFoot('transfer-advance',action).replace('data-action="transfer-advance"',`data-action="transfer-advance" data-id="${x.id}"`):btn('Fechar','close')),{drawer:true});}
function showInvoice(id){const x=records('invoices').find(x=>x.id===id);if(!x)return;if(!x.local&&data.operationMeta)return operationUI.showInvoice(x);openModal(`Invoice #${e(x.number)}`,`<div class="eyebrow">${e(x.supplierName)}${localMark(x)}</div><h3 class="item-detail-title">${e(x.locationName)}</h3><div class="detail-grid">${pair('Total',money(x.total))}${pair('Status financeiro',status(x.status))}${pair('Emissão',date(x.date))}${pair('Vencimento',date(x.dueDate))}</div><div style="margin-top:20px">${notice(x.local?`Arquivo: ${e(x.fileName||'Nenhum')}. ${fileObjects.has(x.id)?'Disponível nesta sessão.':'Reabra o arquivo original para visualizar; o navegador preservou apenas os metadados.'} O arquivo ainda não foi enviado ao Storage S3.`:'Documento consultado no banco. O arquivo e a confirmação S3 não fazem parte deste extrato.',true)}</div>${fileObjects.has(x.id)?btn('Visualizar arquivo','view-file','file', '',`data-id="${x.id}"`):''}`,btn('Fechar','close'),{drawer:true});}
function quick(){openModal('Nova operação',`<div class="supplier-grid" style="grid-template-columns:1fr 1fr">${[['new-order','Ordem de compra','shopping-bag'],['new-count','Contagem de estoque','clipboard-list'],['new-transfer','Transferência interna','arrow-left-right'],['new-production','Lote de preparação','cooking-pot'],['new-invoice','Importar invoice','upload']].map(([action,title,ic])=>`<button class="supplier-card" data-action="${action}" style="text-align:left"><span class="supplier-logo">${icon(ic)}</span><h3 style="margin-top:16px">${title}</h3><p>Registrar na prévia local</p></button>`).join('')}</div>`, '', {subtitle:'Escolha o fluxo que deseja validar'});}
function formStore(){return state.store==='all'?data.locations.find(x=>x.name.includes('Sherwood'))?.id:state.store;}
function formHead(kind){const transfer=kind==='transfer',store=formStore();return `<form id="record-form"><div class="form-grid">${transfer?field('Loja de origem','fromLocationId',select('fromLocationId',options(data.locations,data.locations.find(x=>x.name.includes('Sherwood'))?.id),'required data-change="form-options"'))+field('Loja de destino','toLocationId',select('toLocationId',options(data.locations,data.locations.find(x=>x.name.includes('Natick'))?.id),'required data-change="form-options"')):field('Fornecedor','supplierId',select('supplierId',options(data.suppliers,'','Selecionar fornecedor'),'required data-change="form-options"'))+field('Loja','locationId',select('locationId',options(data.locations,store),'required data-change="form-options"'))}${field(transfer?'Data necessária':'Entrega prevista',transfer?'date':'expectedAt',input(transfer?'date':'expectedAt',transfer?today():tomorrow(),'date','required'))}${field('Referência (opcional)','reference',input('reference','','text','placeholder="Ex.: pedido de sexta-feira"'))}</div><div class="section-title">Itens ${btn('Adicionar item','add-line','plus','sm')}</div><div id="form-lines"></div><div id="form-hint"></div><div class="field" style="margin-top:20px"><label for="notes">Observações</label><textarea id="notes" name="notes" placeholder="Instruções de entrega ou conferência"></textarea></div><p id="form-error" role="alert" class="error-text"></p></form>`;}
function newRecord(kind){draftLines=[{itemId:'',qty:1,uom:''}];openModal(kind==='transfer'?'Nova transferência':'Nova ordem de compra',formHead(kind),localFoot('save-record'),{kind,wide:true,subtitle:kind==='transfer'?'Planeje os itens entre lojas':'Planeje os itens e a data de entrega'});renderLines();}
function eligibleItems(){const form=$('#record-form');if(!form)return [];const values=Object.fromEntries(new FormData(form));if(dialog!=='transfer'&&data.supplierCatalog)return supplierOrderItems(data.supplierCatalog,data.items,local,{locationId:values.locationId,supplierId:values.supplierId});return unique(activeItems().filter(x=>dialog==='transfer'?x.locationId===values.fromLocationId&&x.stores.some(s=>s.id===values.toLocationId):x.locationId===values.locationId&&x.supplierId===values.supplierId)).map(withInternalName);}
function renderLines(){const items=eligibleItems();$('#form-lines').innerHTML=draftLines.map((l,i)=>{const item=items.find(x=>x.id===l.itemId);return `<div class="line-item"><select aria-label="Item ${i+1}" data-line="${i}" data-prop="itemId"><option value="">Selecionar item</option>${items.map(x=>`<option value="${x.id}" ${x.id===l.itemId?'selected':''}>${e(x.sku?x.sku+' · ':'')}${e(x.name)}</option>`).join('')}</select><input type="number" min="0.01" step="any" value="${l.qty}" aria-label="Quantidade do item ${i+1}" data-line="${i}" data-prop="qty"><select aria-label="Unidade do item ${i+1}" data-line="${i}" data-prop="uom">${item?item.units.filter(u=>dialog==='transfer'||u.ordering).map(u=>`<option ${u.name===l.uom?'selected':''}>${e(u.name)}</option>`).join(''):'<option>—</option>'}</select><button type="button" class="icon-btn" aria-label="Remover item ${i+1}" data-action="remove-line" data-index="${i}">${icon('x')}</button></div>`;}).join('');const supplier=$('#supplierId')?.value;$('#form-hint').innerHTML=!items.length?notice(dialog==='transfer'?'Não há itens ativos em comum entre essas lojas.':'Selecione um fornecedor com itens ativos na loja escolhida.',true):supplierName(supplier)==='US Foods'?notice('US Foods: pedido mínimo de 25 cases. Esta prévia permite salvar o planejamento abaixo do mínimo; a conferência final ocorre antes do envio.',true):'';icons();}
async function saveRecord(){const form=$('#record-form');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form)),items=eligibleItems();const lines=draftLines.map(l=>({...l,qty:Number(l.qty),itemUnitId:items.find(x=>x.id===l.itemId)?.units.find(u=>u.name===l.uom)?.itemUnitId||items.find(x=>x.id===l.itemId)?.units.find(u=>u.name===l.uom)?.id,name:items.find(x=>x.id===l.itemId)?.name||''}));let record={...values,lines},error=dialog==='transfer'?validateTransfer(record):validateOrder(record);if(!error&&lines.some(l=>!items.some(x=>x.id===l.itemId)))error='Selecione itens válidos para as lojas e o fornecedor.';if(!error&&lines.some(l=>!items.find(x=>x.id===l.itemId)?.units.some(u=>u.name===l.uom&&(dialog==='transfer'||u.ordering))))error='Selecione uma unidade válida para a operação.';if(error){$('#form-error').textContent=error;return;}const kind=dialog,at=new Date().toISOString();record={...record,id:crypto.randomUUID(),local:true,status:'draft',createdAt:at,number:values.reference||`LOCAL-${String((local[kind==='transfer'?'transfers':'orders'].length)+1).padStart(3,'0')}`,lineCount:lines.length,history:[{at,text:'Rascunho criado'}]};if(kind==='transfer'){record.fromLocationName=locationName(record.fromLocationId);record.toLocationName=locationName(record.toLocationId);}else{record.locationName=locationName(record.locationId);record.supplierName=supplierName(record.supplierId);record.total=null;}local[kind==='transfer'?'transfers':'orders'].unshift(record);audit(`${kind==='transfer'?'Transferência':'Ordem'} criada: ${record.number}`);if(await persist('Rascunho salvo nesta prévia.')){state.store=kind==='transfer'?record.toLocationId:record.locationId;goto(kind==='transfer'?'transfers':'purchases');}}
function countModal(rowId=null){const specific=inventoryItems().find(x=>x.rowId===rowId);const loc=specific?.locationId||formStore();openModal('Nova contagem de estoque',`<form id="count-form"><div class="form-grid">${field('Loja','count-location',select('count-location',options(data.locations,loc),'data-change="count-filter"'))}${field('Localizar por storage area','count-area',select('count-area','<option value="all">Todos os storage areas</option>','data-change="count-area"'))}${field('Data da conferência','count-date',input('count-date',today(),'date','required'))}${field('Momento da conferência','count-moment',select('count-moment','<option>Antes da abertura</option><option>Após o fechamento</option><option>Durante a operação</option>'))}</div><div style="margin-top:20px">${notice('Informe o <strong>total do item na loja, somando todos os storage areas</strong>. O filtro de área apenas ajuda a localizar itens. Campos em branco permanecem sem nova contagem; digite 0 para saldo zero.',true)}</div><div class="input-wrap">${icon('search')}<input data-input="count-search" placeholder="Localizar item na contagem" aria-label="Buscar item na contagem"></div><div id="count-rows"></div><p class="error-text" id="form-error" role="alert"></p></form>`,localFoot('save-count','Salvar contagem'),{kind:'count',wide:true});dialog={kind:'count',specific:rowId,quantities:{}};countAreas(specific?.areaName);renderCount();}
function countAreas(selected){const location=$('#count-location').value,areas=[...new Set(activeItems().filter(x=>x.locationId===location).map(x=>x.areaName).filter(Boolean))].sort();$('#count-area').innerHTML='<option value="all">Todos os storage areas</option>'+areas.map(a=>`<option ${a===selected?'selected':''}>${e(a)}</option>`).join('');}
function renderCount(){const loc=$('#count-location').value,area=$('#count-area').value,q=$('[data-input="count-search"]').value;const rows=activeItems().filter(x=>x.locationId===loc&&(area==='all'||x.areaName===area)&&(!dialog.specific||x.rowId===dialog.specific)&&norm(x.name+' '+x.sku).includes(norm(q)));$('#count-rows').innerHTML=`<div class="table-wrap" style="max-height:350px"><table><thead><tr><th>ITEM / SKU</th><th>TOTAL NA LOJA</th><th>UOM</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${e(x.name)}</strong><small>${e(x.sku||'Preparação')} · ${e(x.areaName||'Sem área')}</small></td><td><input class="count-input" type="number" min="0" step="any" placeholder="—" aria-label="Contagem de ${e(x.name)}" value="${e(dialog.quantities[x.rowId]??'')}" data-count="${x.rowId}"></td><td>${e(x.stocktakeUom||'Sem UOM')}</td></tr>`).join('')}</tbody></table></div>`;}
async function saveCount(){if(!$('#count-form').reportValidity())return;const loc=$('#count-location').value,lines=Object.entries(dialog.quantities).filter(([,v])=>v!=='').map(([id,v])=>{const x=inventoryItems().find(x=>x.rowId===id);const unit=x.units.find(u=>u.stocktake);return {rowId:id,itemId:x.id,name:x.name,qty:Number(v),uom:x.stocktakeUom,locationId:x.locationId,itemUnitId:unit?.itemUnitId||unit?.id,unitId:unit?.unitId,unitFactor:unit?.factor,baseQty:unit?.factor>0?Number(v)*unit.factor:null};}).filter(x=>x.locationId===loc);if(!lines.length||lines.some(l=>!l.uom||!Number.isFinite(l.qty)||l.qty<0)){$('#form-error').textContent='Informe ao menos uma contagem válida, maior ou igual a zero, com unidade cadastrada.';return;}local.counts.push({id:crypto.randomUUID(),locationId:loc,date:$('#count-date').value,moment:$('#count-moment').value,createdAt:new Date().toISOString(),lines});audit(`Contagem local: ${lines.length} itens em ${locationName(loc)}`);if(await persist(`${lines.length} contagens salvas localmente.`)){state.store=loc;goto('inventory');}}
function newProduction(){preparationUI.newBatch();}
function saveProduction(){preparationUI.actions['prep-save-batch']();}
function showProduction(id){preparationUI.showBatch(id);}
function newInvoice(){invoiceFile=null;openModal('Importar invoice',`<form id="invoice-form"><label class="upload-zone" for="invoice-file">${icon('cloud-upload')}<strong id="upload-name">Escolha um PDF ou uma imagem</strong><small>Documento salvo no Storage privado · até 20 MB</small><input class="hidden" id="invoice-file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" data-change="invoice-file"></label><div class="form-grid" style="margin-top:22px">${field('Fornecedor','invoice-supplier',select('invoice-supplier',options(data.suppliers,'','Selecionar'),'required'))}${field('Loja responsável','invoice-location',select('invoice-location',options(data.locations,formStore()),'required'))}${field('Número do invoice','invoice-number',input('invoice-number','','text','required'))}${field('Total (USD)','invoice-total',input('invoice-total','','number','min="0" step="0.01" required'))}${field('Emissão','invoice-date',input('invoice-date',today(),'date','required'))}${field('Vencimento','invoice-due',input('invoice-due','','date','required'))}</div><div style="margin-top:18px">${notice('Confirme a loja explicitamente. O endereço impresso pode divergir da loja responsável. O arquivo será enviado ao Storage privado. O invoice ficará aguardando conferência.',true)}</div><p id="form-error" class="error-text" role="alert"></p></form>`,localFoot('save-invoice','Salvar para conferência'),{kind:'invoice',wide:true});}
async function saveInvoice(){
 if(!$('#invoice-form').reportValidity())return;
 if(!invoiceFile){$('#form-error').textContent='Selecione o documento.';return;}
 const form=$('#invoice-form'),id=form.dataset.invoiceId||crypto.randomUUID();form.dataset.invoiceId=id;
 try{
  if(!form.dataset.recordSaved){await command('batch',{changes:[{action:'invoices',payload:{id,number:$('#invoice-number').value.trim(),supplierId:$('#invoice-supplier').value,locationId:$('#invoice-location').value,total:Number($('#invoice-total').value),date:$('#invoice-date').value,dueDate:$('#invoice-due').value}}]},id);form.dataset.recordSaved='true';}
  const response=await fetch(`/api/invoices/${id}/document`,{method:'PUT',headers:{'Content-Type':invoiceFile.type,'X-File-Name':encodeURIComponent(invoiceFile.name)},body:invoiceFile});const result=await response.json();if(!response.ok)throw Error(result.error);
  await refreshData();closeModal(true);goto('invoices');toast('Invoice e documento salvos e verificados no banco.');
 }catch(error){$('#form-error').textContent=error.message+(form.dataset.recordSaved?' O cadastro foi salvo; tente novamente para concluir o documento.':'');}
}

function showSupplier(id){supplierUI.open(id);}
function showIssue(id){const x=data.issues[id],descriptions={modifier_order_context_missing_or_ambiguous:'O ketchup em packet depende da loja e do canal de venda. É necessário distinguir delivery de venda na loja antes de atribuir o ingrediente.',active_recipe_version_not_unique:'Vendas apontam para receitas sem uma versão ativa única. Revise as versões de shakes e Açaí Smoothie.',recipe_missing:'Vendas Custom Amount não possuem receita correspondente. Confira os lançamentos antes de atribuir consumo.',removal_exceeds_base:'A quantidade removida pelo modifier excede o ingrediente disponível na receita-base. Confira a composição e a unidade.',modifier_mapping_pending:'NO Sprinkles permanece pendente por decisão do usuário. É necessário definir ingrediente e quantidade para permitir a remoção.'};openModal('Pendência de consumo',`<h3 class="item-detail-title">${e(x.label)}</h3><div class="detail-grid">${pair('Loja',e(x.locationName))}${pair('Ocorrências',x.count)}</div><div class="section-title">O que precisa ser conferido</div><p class="item-detail-desc">${e(descriptions[x.code]||'Revise o vínculo do item com a receita.')}</p>${notice('Esta tela é informativa. O extrato não contém as linhas individuais e a prévia não altera os vínculos no banco.',true)}`,btn('Explorar receitas','recipes','notebook-tabs','primary'),{drawer:true});}
function globalSearch(){if(supplierUI.dirty){supplierUI.requestDiscard();return;}if(dialog==='recipe-edit'&&recipeEditor?.dirty){requestRecipeDiscard();return;}openModal('Buscar no workspace',`<div class="input-wrap" style="margin-bottom:20px">${icon('search')}<input class="global-search" aria-label="Busca global" placeholder="Item, SKU, receita ou módulo…" data-input="global" autofocus></div><div id="search-results"></div>`,'',{kind:'search',search:true});searchResults('');}
function searchResults(q){const match=x=>norm(x).includes(norm(q));const result=[...routes.filter(x=>match(x[1])).slice(0,q?4:6).map(x=>({title:x[1],sub:'Módulo',ic:x[2],action:x[0]})),...unique(currentItems()).filter(x=>q&&match(x.name+' '+x.sku)).slice(0,6).map(x=>({title:x.name,sub:`${x.sku||'Sem SKU'} · ${x.supplierName}`,ic:'package',action:'item',id:x.rowId})),...data.recipes.filter(x=>q&&match(x.name)).slice(0,4).map(x=>({title:x.name,sub:'Receita · versão '+x.version,ic:'notebook-tabs',action:'recipe',id:x.id}))];$('#search-results').innerHTML=`<p class="search-hint">${q?'Resultados':'Acesso rápido'}</p>${result.map(x=>`<div role="button" tabindex="0" class="search-result" data-action="${x.action}" ${x.id?`data-id="${x.id}"`:''}>${icon(x.ic)}<div><strong>${e(x.title)}</strong><small>${e(x.sub)}</small></div></div>`).join('')||empty('Nenhum resultado','Tente um nome ou SKU diferente.')}`;icons();}
function exportData(kind){let rows,cols,title;if(kind==='backup'){download('hot-doogy-validacao.json',JSON.stringify({exportedAt:new Date().toISOString(),snapshotDate:data.meta.snapshotDate,local},null,2),'application/json');return;}if(kind==='inventory'){rows=filteredItems();title='inventario';cols=[['SKU','sku'],['Item name','name'],['Internal name','internalName'],['Supplier','supplierName'],['Store','locationName'],['Storage area','areaName'],['Ordering UOM','orderingUom'],['Stocktake UOM','stocktakeUom'],['Última contagem',x=>stockFor(x).qty??stockFor(x).knownSubtotal],['UOM da contagem',x=>stockFor(x).uom],['Data da contagem',x=>countDate(stockFor(x))],['Observação',x=>(stockFor(x).warnings||[]).join(' | ')],['Origem',x=>stockFor(x).source==='no_completed_count'?'Sem contagem registrada':stockFor(x).local?'Contagem local':'Inventário do banco']];}else if(kind==='sales'){rows=selectedSalesPeriod().current;title='vendas';cols=[['Date','date'],['Store','locationName'],['Quantity','quantity'],['Gross Sales','grossSales'],['Discounts','discounts'],['Net Sales','netSales'],['Início do período',()=>state.dateRange?.start||defaultRange().start],['Fim exclusivo do período',()=>state.dateRange?.end||defaultRange().end],['Fuso',()=>'America/New_York']];}else if(kind==='recipes'){rows=recipeRows();title='receitas';cols=[['Name','name'],['Type','type'],['Version','version'],['Status','status'],['Store',x=>x.locationName||'Compartilhada']];}else {rows=state.route==='purchases'?filteredOrders():records('orders').filter(storeMatch);title='ordens';cols=[['Order',shortId],['Supplier','supplierName'],['Store','locationName'],['Delivery','expectedAt'],['Status',x=>labels[x.status]],['Total','total'],['Local',x=>x.local?'Sim':'Não']];}download(`hot-doogy-${title}-${today()}.csv`,safeCsv(rows,cols.map(([label,value])=>({label,value}))),'text/csv;charset=utf-8');}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Arquivo preparado para download.');}

