function receiptForm(el){const order=data.orders.find(x=>x.id===el.dataset.id);openModal('Receber pedido',`<form id="receipt-form"><p>Informe as quantidades efetivamente recebidas. A confirmação registra a entrada no estoque da área selecionada.</p>${order.lines.map(l=>{const areas=inventoryItems().find(i=>i.id===l.itemId&&i.locationId===order.locationId)?.areas.filter(a=>a.locationId===order.locationId)||[];return `<div class="field" data-receipt-line="${l.id}"><label>${e(l.name)} · ${e(l.uom)}</label><input type="number" min="0" step="any" value="0" required><select><option value="">Selecionar área</option>${areas.map(a=>`<option value="${a.id}">${e(a.name)}</option>`).join('')}</select></div>`;}).join('')}<p id="receipt-error" class="error-text"></p></form>`,btn('Cancelar','close')+btn('Confirmar recebimento','cloud-receipt-save','','primary'),{wide:true});dialog={kind:'receipt',order,id:crypto.randomUUID()};}
async function saveReceipt(){if(!$('#receipt-form').reportValidity())return;const {order,id}=dialog;const lines=[...document.querySelectorAll('[data-receipt-line]')].map(el=>({lineId:el.dataset.receiptLine,quantity:Number(el.querySelector('input').value),areaId:el.querySelector('select').value})).filter(x=>x.quantity>0);try{await command('batch',{changes:[{action:'receipt',payload:{id,orderId:order.id,receivedAt:new Date().toISOString(),lines}}]},id);await refreshData();closeModal(true);render();showOrder(order.id);}catch(error){$('#receipt-error').textContent=error.message;}}
function transferStep(el){
 const transfer=data.transfers.find(x=>x.id===el.dataset.id),step=el.dataset.step,shipment=transfer.dispatches.find(x=>x.id===el.dataset.shipment);
 const rows=step==='receive'?shipment.lines:transfer.lines,loc=step==='receive'?transfer.toLocationId:transfer.fromLocationId;
 openModal(step==='approve'?'Aprovar quantidades':step==='dispatch'?'Registrar expedição':'Confirmar recebimento',`<form id="transfer-step-form"><p>${step==='approve'?'Confira as quantidades aprovadas.':'Informe apenas as quantidades efetivamente movimentadas e a área correspondente.'}</p>${rows.map(l=>{const max=step==='receive'?l.quantity-l.receivedQuantity:step==='dispatch'?l.approvedQuantity-l.dispatchedQuantity:l.requestedQuantity;const areas=inventoryItems().find(i=>i.id===l.itemId&&i.locationId===loc)?.areas.filter(a=>a.locationId===loc)||[];return `<div class="field" data-transfer-line="${l.id}"><label>${e(l.name)} · ${e(l.uom)}</label><input type="number" min="0" max="${max}" step="any" value="${Math.max(0,max)}" required>${step==='approve'?'':`<select><option value="">Selecionar área</option>${areas.map(a=>`<option value="${a.id}">${e(a.name)}</option>`).join('')}</select>`}</div>`;}).join('')}<p id="transfer-step-error" class="error-text"></p></form>`,btn('Cancelar','close')+btn('Confirmar','cloud-transfer-save','','primary'),{wide:true});
 dialog={kind:'transfer-step',transfer,step,shipment,commandId:crypto.randomUUID()};
}
async function saveTransferStep(){
 if(!$('#transfer-step-form').reportValidity())return;
 const {transfer,step,shipment,commandId}=dialog;
 const lines=[...document.querySelectorAll('[data-transfer-line]')].map(el=>({[step==='receive'?'transfer_line_id':'request_line_id']:el.dataset.transferLine,quantity:Number(el.querySelector('input').value),...(step!=='approve'?{[step==='receive'?'to_storage_area_id':'from_storage_area_id']:el.querySelector('select').value}:{})})).filter(x=>step==='approve'||x.quantity>0);
 try{await command('batch',{changes:[{action:'transfer_step',payload:{commandId,step,data:{request_id:transfer.id,transfer_id:shipment?.id,lines}}}]},commandId);await refreshData();closeModal(true);render();showTransfer(transfer.id);}catch(error){$('#transfer-step-error').textContent=error.message;}
}
Object.assign(actions,{'boot-retry':()=>openWorkspace(),'cloud-receipt':receiptForm,'cloud-receipt-save':saveReceipt,'legacy-export':()=>download('rascunhos-anteriores.json',JSON.stringify(loadLocal(),null,2),'application/json'),'cloud-refresh':async()=>{await refreshData();render();toast('Dados atualizados.');},'cloud-transfer-step':transferStep,'cloud-transfer-save':saveTransferStep,'cloud-order-advance':async el=>{const x=data.orders.find(x=>x.id===el.dataset.id);await command('batch',{changes:[{action:'orders',payload:{...x,status:'ordered'}}]});await refreshData();closeModal(true);render();showOrder(x.id);}},loginUI.actions,{'login-screen':async()=>{await api('/api/auth/logout',{});session=null;data=null;local=loadLocal({getItem:()=>null});goto('login');}});
for(const [r] of routes)actions[r]=()=>goto(r);
for(const kind of ['inventory','sales','orders','recipes','backup'])actions['export-'+kind]=()=>exportData(kind);
document.addEventListener('click',async ev=>{const route=ev.target.closest('[data-route]');if(route){ev.preventDefault();goto(route.dataset.route);return;}const el=ev.target.closest('[data-action]');if(el){ev.preventDefault();if(el.disabled)return;el.disabled=true;try{await actions[el.dataset.action]?.(el);}catch(error){toast(error.message,'circle-alert');}finally{el.disabled=false;}}else if(ev.target.matches('[data-backdrop]'))closeModal();});
document.addEventListener('submit',ev=>{ev.preventDefault();loginUI.submit(ev.target);});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.change==='item-photo'){updateItemPhoto(el);return;}if(el.dataset.change==='recipe-photo'){updateRecipePhoto(el);return;}if(supplierUI.changed(el))return;if(preparationUI.changed(el))return;if(el.dataset.recipeIndex!=null){updateRecipeField(el);return;}if(el.dataset.line!=null){const l=draftLines[Number(el.dataset.line)];l[el.dataset.prop]=el.value;if(el.dataset.prop==='itemId'){const x=eligibleItems().find(x=>x.id===el.value);l.uom=x?.units.find(u=>dialog==='transfer'?u.stocktake:u.ordering)?.name||'';renderLines();}return;}switch(el.dataset.change){case 'supplier-status':supplierUI.changeStatus(el.value);break;case 'store':state.store=el.value;state.area='all';state.page=1;render();break;case 'period':state.days=Number(el.value);state.dateRange=null;render();break;case 'supplier':state.supplier=el.value;state.page=1;render();break;case 'area':state.area=el.value;state.page=1;render();break;case 'form-options':draftLines=[{itemId:'',qty:1,uom:''}];renderLines();break;case 'count-filter':dialog.specific=null;countAreas();renderCount();break;case 'count-area':dialog.specific=null;renderCount();break;case 'production-item':$('#production-uom').value=preparedItems().find(x=>x.id===el.value)?.stocktakeUom||'';break;case 'invoice-file':{const file=el.files[0];if(file&&file.size<=20*1024*1024&&['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type)){invoiceFile=file;$('#upload-name').textContent=file.name;}else{invoiceFile=null;el.value='';toast('Use um PDF ou imagem de até 20 MB.','circle-alert');}break;}}});
let filterTimer;
document.addEventListener('input',ev=>{const el=ev.target;if(el.type==='file')return;if(supplierUI.changed(el))return;if(preparationUI.input(el))return;if(el.dataset.recipeIndex!=null){updateRecipeField(el);return;}if(el.dataset.input==='recipe-item-search'){recipeEditor.query=el.value;renderRecipePicker();return;}if(el.dataset.count){dialog.quantities[el.dataset.count]=el.value;return;}if(el.dataset.line!=null){draftLines[Number(el.dataset.line)][el.dataset.prop]=el.value;return;}switch(el.dataset.input){case 'global':searchResults(el.value);break;case 'count-search':renderCount();break;case 'filter':{state.q=el.value;state.page=1;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{const start=el.selectionStart;render();const input=$('[data-input="filter"]');input?.focus();input?.setSelectionRange(start,start);},180);break;}}});
document.addEventListener('keydown',ev=>{if(!loginRoutes.includes(state.route)&&(ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();globalSearch();}if(ev.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[role="button"][data-action]')){ev.preventDefault();ev.target.click();}if(ev.key==='Tab'&&dialog){const elements=[...$('#overlay-root').querySelectorAll('button:not([disabled]),input:not([disabled]):not([type="hidden"]),select,textarea,a[href],[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',event=>{if((dialog==='recipe-edit'&&recipeEditor?.dirty)||supplierUI.dirty||preparationUI.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>goto(location.hash.slice(1)||'login'));
let refreshGeneration=0,photoRefresh=null;
function refreshPhotos(){
 if(photoRefresh)return;
 const owner=session;
 photoRefresh=loadCloudPhotos().then(photos=>{if(session!==owner||!data)return;data.photoStorageConnected=true;local.itemPhotos=photos.items;local.recipePhotos=photos.recipes;confirmedLocal=structuredClone(local);if(!dialog&&!supplierUI.dirty&&!preparationUI.dirty)render();}).catch(()=>{if(session===owner&&data)data.photoStorageConnected=false;}).finally(()=>{photoRefresh=null;});
}
async function refreshData(background=false){
 const generation=++refreshGeneration,owner=session,fresh=await api('/api/data');
 if(owner!==session||generation!==refreshGeneration||(background&&(syncing||dialog||supplierUI.dirty||preparationUI.dirty)))return false;
 data=fresh;confirmedLocal=structuredClone(local);refreshPhotos();return true;
}
configureCommit(async next=>{
 if(!session||syncing)throw Error('Aguarde a sincronização antes de salvar.');
 syncing=true;
 try{
  const before=confirmedLocal||loadLocal({getItem:()=>null});
  const changes=[];
  for(const kind of ['orders','transfers','counts','production','invoices'])for(const record of next[kind]||[]){const old=before[kind]?.find(x=>x.id===record.id);if(JSON.stringify(old)!==JSON.stringify(record))changes.push({action:kind,payload:record});}
  for(const [kind,action] of [['supplierItemEdits','catalog'],['recipeEdits','recipe']])for(const [id,value] of Object.entries(next[kind]||{}))if(JSON.stringify(before[kind]?.[id])!==JSON.stringify(value)){changes.push({action,payload:action==='catalog'?{id,shared:next.itemEdits[value.itemId],vendor:value,expectedUpdatedAt:data.supplierCatalog.items.find(x=>x.id===id)?.updatedAt,expectedItemUpdatedAt:data.supplierCatalog.items.find(x=>x.id===id)?.itemUpdatedAt}:{id,...value,expectedVersionId:data.recipes.find(x=>x.id===id)?.versionId}});}
  if(changes.length)await command('batch',{changes},next.pendingCommandId||(next.pendingCommandId=crypto.randomUUID()));
  const photos={itemPhotos:next.itemPhotos,recipePhotos:next.recipePhotos};
  Object.assign(next,loadLocal({getItem:()=>null}),photos);delete next.pendingCommandId;
  local=next;confirmedLocal=structuredClone(local);try{await refreshData();}catch(error){toast('Salvo no banco. Atualização da tela pendente: '+error.message,'circle-alert');}
 }finally{syncing=false;}
});
createRefreshLoop({canRefresh:()=>!!session&&!!data&&!loginRoutes.includes(state.route)&&!syncing&&!dialog&&!document.hidden&&!supplierUI.dirty&&!preparationUI.dirty,refresh:async()=>{if(await refreshData(true))render();},onError:error=>{if(error.status===401||error.status===403){session=null;data=null;render();}else toast('Sem atualização: '+error.message,'circle-alert');}});
try{session=await api('/api/auth/session');}catch{session=null;}if(session)await openWorkspace();else render();

document.addEventListener('keydown',ev=>{
  const tab=ev.target.closest('.recipe-detail-tabs [role="tab"]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(ev.key))return;
  ev.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role="tab"]')],index=tabs.indexOf(tab);
  const next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(index+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;
  selectRecipeTab(tabs[next].dataset.tab);tabs[next].focus();
});
